<style>
.support-launch{position:fixed;right:24px;bottom:24px;z-index:1300;border:1px solid #e4c447;border-radius:999px;padding:13px 19px;background:linear-gradient(135deg,#f0cf56,#c99e1d);color:#171a1c;font:700 14px 'Outfit',Arial,sans-serif;box-shadow:0 8px 24px rgba(207,169,41,.25);cursor:pointer}.support-unread-badge{position:absolute;top:-7px;right:-5px;display:grid;min-width:22px;height:22px;padding:0 6px;place-items:center;border:2px solid #101417;border-radius:999px;background:#ed3b4b;color:#fff;font:800 11px/1 Arial,sans-serif;box-shadow:0 2px 8px rgba(0,0,0,.35)}.support-unread-badge[hidden]{display:none}
.support-panel{position:fixed;right:24px;bottom:80px;z-index:1300;width:min(390px,calc(100vw - 28px));height:min(560px,calc(100vh - 110px));display:none;flex-direction:column;overflow:hidden;background:#191e24;border:1px solid #303740;border-radius:18px;box-shadow:0 18px 48px rgba(0,0,0,.42);color:#edf0f3;font-family:'Outfit',Arial,sans-serif}
.support-panel.is-open{display:flex}.support-head{display:flex;align-items:center;justify-content:space-between;padding:14px 17px;background:#11161a;border-bottom:1px solid #303740;color:#f0cf56}.support-head-title{display:flex;flex-direction:column;gap:2px}.support-head-title small{color:#97a2ad;font-size:11px;font-weight:500}.support-close{border:0;background:transparent;color:#d9dee3;font-size:24px;cursor:pointer;line-height:1}
.support-log{flex:1;overflow-y:auto;padding:15px;background:#12171b}.support-msg{max-width:88%;margin:0 0 11px;padding:9px 12px;border-radius:13px;background:#20262d;border:1px solid #303740;color:#e7eaed;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.support-msg.is-own{margin-left:auto;background:#8d7117;border-color:#b59527;color:#fff;border-top-right-radius:4px}.support-msg-meta{display:block;margin-top:5px;color:#aab4be;font-size:10px}.support-notice{padding:8px 14px;color:#aeb8c2;font-size:12px}.support-notice.is-error{color:#ff9a9e}.support-compose{display:flex;gap:8px;padding:12px;border-top:1px solid #303740;background:#191e24}.support-compose input{min-width:0;flex:1;border:1px solid #39434c;border-radius:10px;padding:10px 11px;background:#11171c;color:#f4f6f8;font:inherit;font-size:14px}.support-compose input::placeholder{color:#84909b}.support-compose button,.support-reopen{border:0;border-radius:10px;padding:0 14px;background:#d1ad31;color:#171a1c;font-weight:700;cursor:pointer}.support-compose button:disabled{opacity:.55;cursor:not-allowed}.support-reopen{margin:0 12px 12px;padding:10px}.support-reopen[hidden]{display:none}
.shop-ai-launch{bottom:86px!important}.shop-ai-panel{bottom:144px!important}
@media(max-width:640px){.support-launch{right:14px;bottom:14px}.support-panel{right:14px;bottom:70px}.shop-ai-launch{right:14px;bottom:76px!important}.shop-ai-panel{right:14px;bottom:134px!important}}
</style>
<section id="support-panel" class="support-panel" aria-label="Chat hỗ trợ khách hàng" aria-hidden="true">
    <div class="support-head"><div class="support-head-title"><strong>Chat hỗ trợ DailyMart</strong><small id="support-connection">Đang kết nối…</small></div><button type="button" id="support-close" class="support-close" aria-label="Đóng">&times;</button></div>
    <div id="support-log" class="support-log" role="log" aria-live="polite"></div>
    <div id="support-notice" class="support-notice" aria-live="polite">Tin nhắn được lưu để nhân viên có thể phản hồi khi bạn quay lại.</div>
    <button type="button" id="support-reopen" class="support-reopen" hidden>Mở lại cuộc trò chuyện</button>
    <form id="support-form" class="support-compose"><input id="support-input" maxlength="2000" autocomplete="off" placeholder="Nhập tin nhắn..." aria-label="Tin nhắn hỗ trợ"><button type="submit" disabled>Gửi</button></form>
</section>
<button type="button" id="support-launch" class="support-launch" aria-expanded="false" aria-controls="support-panel">✦ Chat hỗ trợ<span id="support-unread-badge" class="support-unread-badge" aria-label="Tin nhắn chưa đọc" hidden></span></button>
<script src="/socket.io/socket.io.js"></script>
<script>
(function(){
    const panel=document.getElementById('support-panel'),launch=document.getElementById('support-launch'),close=document.getElementById('support-close'),badge=document.getElementById('support-unread-badge');
    const log=document.getElementById('support-log'),form=document.getElementById('support-form'),input=document.getElementById('support-input'),send=form.querySelector('button');
    const connection=document.getElementById('support-connection'),notice=document.getElementById('support-notice'),reopen=document.getElementById('support-reopen');
    const csrf=<?php echo json_encode($_SESSION['shop_csrf'] ?? '', JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;
    const openUrl='/Baitaplon/store.php?url=SupportChat/Open',tokenUrl='/Baitaplon/store.php?url=SupportChat/Token',unreadUrl='/Baitaplon/store.php?url=SupportChat/Unread';
    const historyUrl=id=>'/Baitaplon/store.php?url=SupportChat/History/'+encodeURIComponent(id);
    let conversationId=null,socket=null,busy=false,shown=new Set(),notified=new Set(),isOpen=false,renewTimer=null,tokenExpiresAt=0,unreadCount=0,unreadRevision=0;
    function setPanel(value){isOpen=value;panel.classList.toggle('is-open',value);panel.setAttribute('aria-hidden',String(!value));launch.setAttribute('aria-expanded',String(value));if(value)input.focus();}
    function setUnreadCount(value){unreadCount=Math.max(0,Number(value)||0);badge.textContent=unreadCount>99?'99+':String(unreadCount);badge.hidden=unreadCount===0;launch.setAttribute('aria-label',unreadCount?`Chat hỗ trợ, ${unreadCount} tin nhắn chưa đọc`:'Chat hỗ trợ');}
    async function syncUnread(){const revision=unreadRevision;try{const result=await api(unreadUrl);if(revision===unreadRevision){if(result.conversationId)conversationId=Number(result.conversationId);setUnreadCount(result.unreadCount);}}catch(_) {}}
    function markAsRead(){unreadRevision++;setUnreadCount(0);if(socket&&socket.connected&&conversationId)socket.emit('support:read',conversationId);}
    function setNotice(text,error=false){notice.textContent=text;notice.classList.toggle('is-error',error);}
    function setStatus(status){const closed=status==='closed';send.disabled=closed||!conversationId||!socket||!socket.connected;input.disabled=closed||!conversationId;reopen.hidden=!closed;connection.textContent=closed?'Cuộc trò chuyện đã kết thúc':(socket&&socket.connected?'Đang trực tuyến':'Đang kết nối…');if(closed)setNotice('Cuộc trò chuyện đã kết thúc. Bạn có thể mở lại để tiếp tục.',false);}
    function addMessage(message){const id=String(message.id);if(shown.has(id))return;shown.add(id);const senderType=message.senderType||message.sender_type;const senderName=message.senderName||message.sender_name;const createdAt=message.createdAt||message.created_at;const item=document.createElement('div');item.className='support-msg'+(senderType==='customer'?' is-own':'');item.dataset.messageId=id;item.textContent=String(message.body||'');const meta=document.createElement('small');meta.className='support-msg-meta';meta.textContent=(senderType==='customer'?'Bạn':String(senderName||'Quản trị viên'))+' · '+new Date(createdAt||Date.now()).toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'});item.appendChild(meta);log.appendChild(item);log.scrollTop=log.scrollHeight;}
    async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Không thể kết nối chat.');return result;}
    async function connect(){if(!window.io)throw new Error('Không tải được thư viện chat. Hãy tải lại trang.');socket=window.io({path:'/socket.io/',transports:['websocket','polling'],auth:async callback=>{try{const result=await api(tokenUrl);tokenExpiresAt=Number(result.expiresAt)*1000;callback({token:result.token});}catch(error){callback({token:''});setNotice(error.message,true);}},reconnection:true});socket.on('connect',async()=>{clearTimeout(renewTimer);renewTimer=setTimeout(()=>{if(socket&&socket.connected){socket.disconnect();socket.connect();}},Math.max(1000,tokenExpiresAt-Date.now()-60000));connection.textContent='Đang trực tuyến';if(conversationId){socket.emit('support:join',conversationId,async result=>{if(!result||!result.ok){setNotice(result&&result.error||'Không mở được cuộc trò chuyện.',true);return;}setStatus(result.status);if(isOpen){try{const data=await api(historyUrl(conversationId));data.messages.forEach(addMessage);setStatus(data.conversation.status);markAsRead();}catch(error){setNotice(error.message,true);}}});}else setStatus('open');});socket.on('disconnect',()=>{clearTimeout(renewTimer);connection.textContent='Mất kết nối · đang thử lại';send.disabled=true;});socket.on('connect_error',error=>{connection.textContent='Không kết nối được';setNotice(error.message||'Lỗi kết nối chat.',true);});socket.on('support:message',message=>{const senderType=message.senderType||message.sender_type;const id=String(message.id);if(notified.has(id))return;notified.add(id);const matches=Number(message.conversationId||message.conversation_id)===Number(conversationId);if(senderType==='customer'){if(matches)addMessage(message);return;}if(senderType!=='admin')return;if(matches&&isOpen){addMessage(message);markAsRead();}else{unreadRevision++;setUnreadCount(unreadCount+1);}});socket.on('support:customer-unread-count',count=>{unreadRevision++;setUnreadCount(count);});socket.on('support:status',payload=>{if(Number(payload.conversationId)===Number(conversationId))setStatus(payload.status);});}
    async function openConversation(){if(busy)return;busy=true;send.disabled=true;setNotice('Đang mở cuộc trò chuyện…');try{const data=await api(openUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({csrf_token:csrf})});conversationId=data.conversation.id;shown.clear();log.replaceChildren();data.messages.forEach(addMessage);markAsRead();if(!socket)await connect();else if(socket.connected)socket.emit('support:join',conversationId,result=>{if(result&&result.ok)setStatus(result.status);});setNotice('Tin nhắn được lưu để nhân viên có thể phản hồi khi bạn quay lại.');}catch(error){setNotice(error.message,true);}finally{busy=false;send.disabled=!socket||!socket.connected;input.focus();}}
    launch.addEventListener('click',()=>{setPanel(!isOpen);if(isOpen)openConversation();});close.addEventListener('click',()=>setPanel(false));
    reopen.addEventListener('click',openConversation);
    form.addEventListener('submit',event=>{event.preventDefault();const message=input.value.trim();if(!message||!socket||!socket.connected||!conversationId||busy)return;busy=true;send.disabled=true;socket.emit('support:send',{conversationId,message},result=>{if(!result||!result.ok){setNotice(result&&result.error||'Không gửi được tin nhắn.',true);}else{input.value='';setNotice('Đã gửi tin nhắn.');}busy=false;setStatus('open');input.focus();});});
    syncUnread();connect().catch(error=>{connection.textContent='Không kết nối được';setNotice(error.message,true);});
})();
</script>
